                    b.HasData(
                        new
                        {
                            Slug = "offer",
                            BodyHtml = "<p><strong>Чернетка.</strong> Остаточний текст оферти надасть продавець.</p><h2>1. Загальні положення</h2><p>Оформлюючи замовлення, покупець погоджується з умовами цієї оферти.</p><h2>2. Замовлення</h2><p>Замовлення оформлюється на сайті без реєстрації. Після оформлення покупець отримує номер замовлення.</p><h2>3. Ціна й оплата</h2><p>Ціни вказано в гривнях. Способи оплати: онлайн карткою, післяплата, оплата під час самовивозу.</p><h2>4. Доставка</h2><p>Новою поштою по Україні за тарифами перевізника або самовивіз у Бучі.</p><h2>5. Повернення</h2><p>Умови повернення описано на сторінці «Повернення й обмін».</p><h2>6. Продавець</h2><p>Реквізити продавця вказано нижче й на сторінці замовлення.</p>",
                            Lead = "Договір купівлі-продажу між продавцем і покупцем інтернет-магазину.",
                            Title = "Публічна оферта",
                            UpdatedAt = new DateTimeOffset(new DateTime(2026, 10, 28, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0))
                        },
                        new
                        {
                            Slug = "privacy",
                            BodyHtml = "<p><strong>Чернетка.</strong> Остаточний текст надасть продавець.</p><h2>Які дані</h2><p>Ім'я, телефон, за бажанням email, населений пункт, відділення або адреса доставки, коментар до замовлення.</p><h2>Навіщо</h2><p>Щоб виконати й доставити замовлення, повідомити про його статус і прийняти оплату.</p><h2>Аналітика</h2><p>Ми рахуємо перегляди й покупки без передачі імені, телефону чи email в аналітичні системи.</p><h2>Зберігання</h2><p>Дані зберігаються на захищеному сервері. Доступ до них мають лише працівники, які обробляють замовлення.</p><h2>Ваші права</h2><p>Щоб переглянути, виправити або видалити свої дані, зателефонуйте чи напишіть у магазин.</p>",
                            Lead = "Які дані ми збираємо під час замовлення і як їх використовуємо.",
                            Title = "Політика приватності",
                            UpdatedAt = new DateTimeOffset(new DateTime(2026, 10, 28, 0, 0, 0, 0, DateTimeKind.Unspecified), new TimeSpan(0, 0, 0, 0, 0))
                        },
                        new
                        {
                            Slug = "returns",
                            BodyHtml = "<p><strong>Чернетка.</strong> Остаточні умови продавець погодить за законом «Про захист прав споживачів».</p><h2>Строк</h2><p>Товар належної якості можна повернути протягом 14 днів, якщо він не був у використанні й збережено товарний вигляд.</p><h2>Як повернути</h2><p>Зателефонуйте менеджеру й назвіть номер замовлення. Можна повернути все замовлення або окремі товари.</p><h2>Кошти</h2><p>Оплату карткою повертаємо на ту саму картку. Оплату під час отримання повертаємо способом, який погодите з менеджером. На повернення видаємо чек.</p>",
